#include <NexumPresetHeader.h>
#include <NexumDesign.h>
#include <NexumHeaderOutput.h>
#include "NexumFxProcessor.h"
#include "FxPage.h"
#include "SynthSidebar.h"
#include <BinaryData.h>
namespace noctrl {
class NexumFxEditor:public juce::AudioProcessorEditor,private juce::Timer,public juce::DragAndDropContainer {
 NexumFxProcessor& p;OscModernTheme theme;nxf::PresetHeaderStyle presetStyle{UiStyle::blue()};SynthSidebar sidebar{p,2,"FX"};nxf::SidebarTab rackTab{"FX"},libraryTab{"PRESETS"};FxPage page;AssetBrowser presetPage{p,0,AssetKind::Fx};AssetLibrary headerLibrary{AssetKind::Fx};juce::ComboBox presetNames;juce::Label presetArtist,presetDescription;juce::TextButton savePreset{"SAVE"},previousPreset{"<"},nextPreset{">"};int headerTicks=0;AutomationSlider mix,output;nxf::HeaderControl mixControl{mix,"MIX",UiStyle::blue()},masterControl{output,"MASTER",UiStyle::blue()};nxf::HeaderAction bypass{false,UiStyle::blue()};
 std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment> gainLink,mixLink;std::unique_ptr<juce::AudioProcessorValueTreeState::ButtonAttachment> bypassLink;
 juce::Image logo;juce::TooltipWindow tooltip{this,600};
 void timerCallback()override{sidebar.refreshMacros();if(++headerTicks%25==0)refreshPresetList();updatePresetHeader();mixControl.refresh();masterControl.refresh();bypass.setColour(juce::TextButton::textColourOnId,UiStyle::blue());bypass.setColour(juce::TextButton::textColourOffId,nd::colour(juce::Colour(0xff91a7b9)));repaint();}
 void refreshPresetList(){headerLibrary.refresh();auto current=presetNames.getText();presetNames.clear(juce::dontSendNotification);for(int i=0;i<(int)headerLibrary.entries.size();++i)presetNames.addItem(headerLibrary.entries[i].name,i+1);presetNames.setText(current,juce::dontSendNotification);}
 void updatePresetHeader(){using namespace juce;auto name=p.state.state.getProperty("fxPresetName","Init").toString();presetNames.setText(name,dontSendNotification);auto values=PresetMetadata::fromJson(JSON::parse(p.state.state.getProperty("fxHeaderMetadata").toString()));presetArtist.setText(values.author.isEmpty()?String::charToString(0x2014):values.author,dontSendNotification);presetDescription.setText(values.description.isEmpty()?String::charToString(0x2014):values.description,dontSendNotification);}
 void remember(const juce::File& file,const PresetMetadata& metadata){p.state.state.setProperty("fxPresetFile",file.getFullPathName(),nullptr);p.state.state.setProperty("fxPresetName",metadata.name,nullptr);p.state.state.setProperty("fxHeaderMetadata",juce::JSON::toString(metadata.toJson()),nullptr);updatePresetHeader();}
 void loadPreset(int index){using namespace juce;if(index<0||index>=(int)headerLibrary.entries.size())return;auto entry=headerLibrary.entries[index];var doc;auto result=FxLibrary::read(entry.file,doc);if(result.wasOk())result=FxLibrary::apply(p,doc,0);if(result.failed()){AlertWindow::showMessageBoxAsync(MessageBoxIconType::WarningIcon,"Preset",result.getErrorMessage());return;}PresetMetadata metadata;metadata.name=entry.name;metadata.author=entry.author;metadata.description=entry.description;metadata.notes=entry.notes;metadata.tags=entry.tags;metadata.category=entry.category;metadata.rating=entry.rating;remember(entry.file,metadata);}
 void navigatePreset(int direction){refreshPresetList();int count=(int)headerLibrary.entries.size();if(!count)return;int index=direction>0?-1:0;auto file=p.state.state.getProperty("fxPresetFile").toString();for(int i=0;i<count;++i)if(headerLibrary.entries[i].file.getFullPathName()==file){index=i;break;}loadPreset((index+direction+count)%count);}
 void saveCurrentPreset(bool overwrite){using namespace juce;auto doc=FxLibrary::capture(p,0);if(FxLibrary::validate(doc).failed()){AlertWindow::showMessageBoxAsync(MessageBoxIconType::InfoIcon,"Preset","Add an effect before saving a chain.");return;}auto metadata=PresetMetadata::fromJson(JSON::parse(p.state.state.getProperty("fxHeaderMetadata").toString()));metadata.name=p.state.state.getProperty("fxPresetName","New effect chain").toString();if(overwrite){auto path=p.state.state.getProperty("fxPresetFile").toString();if(!File::isAbsolutePath(path)||!File(path).existsAsFile())return;doc.getDynamicObject()->setProperty("metadata",metadata.toJson());auto result=FxLibrary::writeJson(File(path),doc);if(result.failed())AlertWindow::showMessageBoxAsync(MessageBoxIconType::WarningIcon,"Preset",result.getErrorMessage());else remember(File(path),metadata);return;}auto* dialog=new AlertWindow("Create new preset","Preset name",MessageBoxIconType::NoIcon,this);dialog->addTextEditor("name",metadata.name=="Init"?"New effect chain":metadata.name+" Copy");dialog->addButton("Save",1);dialog->addButton("Cancel",0);auto safe=Component::SafePointer<NexumFxEditor>(this);dialog->enterModalState(true,ModalCallbackFunction::create([safe,dialog,doc,metadata](int choice)mutable{if(!safe||choice!=1)return;metadata.name=dialog->getTextEditorContents("name").trim();File saved;auto result=FxLibrary::save(AssetLibrary::defaultRoot(AssetKind::Fx),metadata,doc,saved);if(result.failed())AlertWindow::showMessageBoxAsync(MessageBoxIconType::WarningIcon,"Preset",result.getErrorMessage());else{safe->remember(saved,metadata);safe->refreshPresetList();safe->presetPage.syncFxLibrary();}}),true);}
public:
 NexumFxEditor(NexumFxProcessor& processor):AudioProcessorEditor(processor),p(processor),page(p,true){using namespace juce;setLookAndFeel(&theme);theme.attach(*this,"Nexum FX");logo=ImageCache::getFromMemory(BinaryData::NEXUM_FX_png,BinaryData::NEXUM_FX_pngSize);addAndMakeVisible(page);addAndMakeVisible(presetPage);presetPage.setVisible(false);for(auto* c:std::initializer_list<Component*>{&presetNames,&savePreset,&previousPreset,&nextPreset,&presetArtist,&presetDescription})addAndMakeVisible(c);presetStyle.attach(presetNames,savePreset,previousPreset,nextPreset,presetArtist,presetDescription);presetNames.setComponentID("fx-preset-name");refreshPresetList();presetNames.onChange=[this]{loadPreset(presetNames.getSelectedId()-1);};previousPreset.onClick=[this]{navigatePreset(-1);};nextPreset.onClick=[this]{navigatePreset(1);};savePreset.onClick=[this]{PopupMenu menu;menu.addItem(1,"Create new preset...");auto path=p.state.state.getProperty("fxPresetFile").toString();menu.addItem(2,"Overwrite preset",File::isAbsolutePath(path)&&File(path).existsAsFile());auto safe=Component::SafePointer<NexumFxEditor>(this);menu.showMenuAsync(PopupMenu::Options().withTargetComponent(&savePreset),[safe](int choice){if(safe&&choice>0)safe->saveCurrentPreset(choice==2);});};addAndMakeVisible(mixControl);addAndMakeVisible(masterControl);addAndMakeVisible(bypass);mix.bindAutomation(p.state.getParameter("fxMix"),&p);mix.getProperties().set("parameterIndex",p.state.getParameter("fxMix")->getParameterIndex());mix.setDoubleClickReturnValue(true,1);mixLink=std::make_unique<AudioProcessorValueTreeState::SliderAttachment>(p.state,"fxMix",mix);mix.textFromValueFunction=[](double v){return String(v*100,0)+" %";};mix.valueFromTextFunction=[](const String& v){return v.getDoubleValue()/100.;};mix.setTooltip("Whole rack dry/wet mix / right-click: host automation");output.bindAutomation(p.state.getParameter("fxOutput"),&p);output.getProperties().set("parameterIndex",p.state.getParameter("fxOutput")->getParameterIndex());output.textFromValueFunction=[](double v){return String(v,1)+" dB";};output.setDoubleClickReturnValue(true,0);gainLink=std::make_unique<AudioProcessorValueTreeState::SliderAttachment>(p.state,"fxOutput",output);output.textFromValueFunction=[](double v){return String(v,1)+" dB";};output.updateText();output.setTooltip("Output gain / right-click: host automation");bypass.setClickingTogglesState(true);bypass.setTooltip("Whole rack bypass. Blue: bypass active.");bypass.getProperties().set("parameterIndex",p.state.getParameter("fxBypass")->getParameterIndex());bypass.setColour(TextButton::buttonColourId,nd::colour(Colour(0xff0c1822)));bypass.setColour(TextButton::buttonOnColourId,nd::colour(Colour(0xff0c1822)));bypassLink=std::make_unique<AudioProcessorValueTreeState::ButtonAttachment>(p.state,"fxBypass",bypass);addAndMakeVisible(sidebar);sidebar.setLogo(logo);sidebar.getProperties().set("completeBrandLogo",true);sidebar.addAndMakeVisible(rackTab);sidebar.addAndMakeVisible(libraryTab);rackTab.setToggleState(true,dontSendNotification);rackTab.onClick=[this]{page.setVisible(true);presetPage.setVisible(false);rackTab.setToggleState(true,dontSendNotification);libraryTab.setToggleState(false,dontSendNotification);};libraryTab.onClick=[this]{page.setVisible(false);presetPage.setVisible(true);presetPage.syncFxLibrary();refreshPresetList();rackTab.setToggleState(false,dontSendNotification);libraryTab.setToggleState(true,dontSendNotification);};setSize(1332,850);timerCallback();startTimerHz(25);}
 ~NexumFxEditor()override{stopTimer();mixLink.reset();gainLink.reset();bypassLink.reset();setLookAndFeel(nullptr);}
 void resized()override{sidebar.setBounds(0,0,92,getHeight());rackTab.setBounds(0,67,92,38);libraryTab.setBounds(0,105,92,38);page.setBounds(108,78,1208,getHeight()-94);presetPage.setBounds(108,78,1208,680);nxf::layoutPresetHeader(92,getWidth()-284,presetNames,savePreset,previousPreset,nextPreset,presetArtist,presetDescription);bypass.setBounds(getWidth()-192,0,38,66);mixControl.setBounds(getWidth()-154,1,58,64);masterControl.setBounds(getWidth()-96,1,58,64);}
 int getControlParameterIndex(juce::Component& control)override{for(auto* c=&control;c&&c!=this;c=c->getParentComponent())if(c->getProperties().contains("parameterIndex"))return (int)c->getProperties()["parameterIndex"];return -1;}
 void paint(juce::Graphics& g)override{nd::Scope suitScope("controls");using namespace juce;g.fillAll(UiStyle::canvas());g.setColour(Colour(0xff17212a));g.fillRect(92,0,getWidth()-92,66);g.setColour(Colour(0xff344650));g.drawHorizontalLine(66,92.f,(float)getWidth());nxf::paintPresetHeader(g,92,getWidth()-284);nxf::drawHeaderMeters(g,getWidth()-36,{p.masterMeters[0].load(),p.masterMeters[1].load()},UiStyle::blue());}

};
juce::AudioProcessorEditor* NexumFxProcessor::createEditor(){return new NexumFxEditor(*this);}
}
